head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[trigger > M > setBackgroundImage]<br/>type=button 일때 Trigger 컴포넌트의 배경 이미지를 URL 로 설정합니다.",
    "validation" : [
        "imgUrl(필수) 파라미터로 배경으로 사용할 이미지의 URL 을 설정할 수 있어야 합니다.",
        "상대경로를 설정할 수 있어야 합니다.",        
        "절대경로를 설정할 수 있어야 합니다.",        
        "프로토콜 포함 경로를 설정할 수 있어야 합니다.",        
        "PNG, JPG, JPEG, GIF, SVG 등 브라우저가 지원하는 모든 이미지 파일을 사용할 수 있어야 합니다.",
        "설정한 URL 값은 CSS 의 background-image 속성에 적용되어야 합니다.",
        "배경 이미지와 관련된 background-repeat, background-size 등의 속성은 CSS 설정값 또는 브라우저의 기본값이 적용되어야 합니다.",     
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createBasicTrigger();    
}
